<script>
  (function() {
    const confirmBtn = document.getElementById('confirmPurgeBtn');
    const lockBtn = document.getElementById('lockTerminalBtn');
    const progressContainer = document.getElementById('purgeProgressState');
    const progressBar = document.getElementById('progressBar');
    const progressPercent = document.getElementById('progressPercent');

    if (confirmBtn && progressContainer && progressBar && progressPercent) {
      confirmBtn.addEventListener('click', function() {
        confirmBtn.disabled = true;
        confirmBtn.classList.add('opacity-50', 'cursor-not-allowed');
        progressContainer.classList.remove('hidden');
        progressContainer.classList.add('flex');

        let val = 0;
        const interval = setInterval(function() {
          val += 20;
          progressBar.style.width = val + '%';
          progressPercent.textContent = val + '%';

          if (val >= 100) {
          clearInterval(interval);
            setTimeout(function() {
                sessionStorage.clear();
                localStorage.removeItem('cvsu_docusecure_token');

                window.location.href = "{{ route('login') }}";
            }, 300);
          }
        }, 120);
      });
    }

    if (lockBtn) {
      lockBtn.addEventListener('click', function() {
        const confirmed = confirm('Lock CEIT lab workstation screen? Enter your student passkey upon return.');
        if (confirmed) {
          window.location.hash = '#terminal-locked';
        }
      });
    }
  })();
</script></main></div>




